#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define WIDTH 800
#define HEIGHT 600

typedef struct { float x, y, z; } Vector;
typedef struct { Vector origin; Vector direction; } Ray;
typedef struct { Vector center; float radius; } Sphere;
typedef struct { float t; Vector point; Vector normal; int hit; } Hit;

Vector vector_create(float x, float y, float z) {
    Vector v;
    v.x = x; v.y = y; v.z = z;
    return v;
}

Vector vector_add(Vector a, Vector b) {
    return vector_create(a.x + b.x, a.y + b.y, a.z + b.z);
}

Vector vector_subtract(Vector a, Vector b) {
    return vector_create(a.x - b.x, a.y - b.y, a.z - b.z);
}

Vector vector_multiply(Vector a, float s) {
    return vector_create(a.x * s, a.y * s, a.z * s);
}

float vector_dot(Vector a, Vector b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

float vector_length(Vector a) {
    return sqrtf(a.x * a.x + a.y * a.y + a.z * a.z);
}

Vector vector_normalize(Vector a) {
    float len = vector_length(a);
    return vector_create(a.x / len, a.y / len, a.z / len);
}

Ray ray_create(Vector origin, Vector direction) {
    Ray r;
    r.origin = origin;
    r.direction = vector_normalize(direction);
    return r;
}

Vector ray_at(Ray r, float t) {
    return vector_add(r.origin, vector_multiply(r.direction, t));
}

Hit sphere_intersect(Ray ray, Sphere sphere) {
    Hit h;
    Vector oc = vector_subtract(ray.origin, sphere.center);
    float a = vector_dot(ray.direction, ray.direction);
    float b = 2.0f * vector_dot(oc, ray.direction);
    float c = vector_dot(oc, oc) - sphere.radius * sphere.radius;
    float disc = b * b - 4.0f * a * c;

    if (disc < 0.0f) {
        h.t = 0.0f;
        h.point = vector_create(0.0f, 0.0f, 0.0f);
        h.normal = vector_create(0.0f, 0.0f, 0.0f);
        h.hit = 0;
        return h;
    }

    float t = (-b - sqrt(disc)) / (2.0f * a);
    if (t <= 0.001f) {
        t = (-b + sqrt(disc)) / (2.0f * a);
        if (t <= 0.001f) {
            h.t = 0.0f;
            h.point = vector_create(0.0f, 0.0f, 0.0f);
            h.normal = vector_create(0.0f, 0.0f, 0.0f);
            h.hit = 0;
            return h;
        }
    }

    h.t = t;
    h.point = ray_at(ray, t);
    h.normal = vector_normalize(vector_subtract(h.point, sphere.center));
    h.hit = 1;
    return h;
}

Hit plane_intersect(Ray ray, float plane_y) {
    Hit h;
    if (fabsf(ray.direction.y) < 0.0001f) {
        h.t = 0.0f;
        h.point = vector_create(0.0f, 0.0f, 0.0f);
        h.normal = vector_create(0.0f, 0.0f, 0.0f);
        h.hit = 0;
        return h;
    }

    float t = (plane_y - ray.origin.y) / ray.direction.y;
    if (t <= 0.001f) {
        h.t = 0.0f;
        h.point = vector_create(0.0f, 0.0f, 0.0f);
        h.normal = vector_create(0.0f, 0.0f, 0.0f);
        h.hit = 0;
        return h;
    }

    h.t = t;
    h.point = ray_at(ray, t);
    h.normal = vector_create(0.0f, 1.0f, 0.0f);
    h.hit = 1;
    return h;
}

Vector sky_color(Vector direction) {
    float t = (direction.y + 1.0f) * 0.5f;
    Vector white = vector_create(1.0f, 1.0f, 1.0f);
    Vector blue = vector_create(0.5f, 0.7f, 1.0f);
    return vector_add(vector_multiply(white, 1.0f - t), vector_multiply(blue, t));
}

int is_in_shadow(Vector point, Vector normal, Vector light_dir, Sphere sphere) {
    Ray shadow_ray = ray_create(vector_add(point, vector_multiply(normal, 0.001f)), light_dir);
    Hit h = sphere_intersect(shadow_ray, sphere);
    return h.hit;
}

Vector trace(Ray ray, Sphere sphere, Vector light_dir) {
    Hit hit = sphere_intersect(ray, sphere);
    Hit plane = plane_intersect(ray, -1.5f);

    if (plane.hit && (!hit.hit || plane.t <= hit.t)) {
        hit = plane;
    }

    if (!hit.hit) {
        return sky_color(ray.direction);
    }

    float intensity;
    if (is_in_shadow(hit.point, hit.normal, light_dir, sphere)) {
        intensity = 0.2f;
    } else {
        float diffuse = fmax(0.0, vector_dot(hit.normal, light_dir));
        intensity = 0.2f + 0.8f * diffuse;
    }

    if (hit.normal.y == 1.0f && hit.normal.x == 0.0f && hit.normal.z == 0.0f) {
        int checker = (int)(floor(hit.point.x) + floor(hit.point.z));
        float shade = (checker % 2 == 0) ? 0.9f : 0.4f;
        shade = shade * intensity;
        return vector_create(shade, shade, shade);
    }

    return vector_multiply(vector_create(1.0f, 0.2f, 0.2f), intensity);
}

Vector **allocate_image(int width, int height) {
    Vector **image = (Vector **)malloc(height * sizeof(Vector *));
    for (int y = 0; y < height; y++) {
        image[y] = (Vector *)malloc(width * sizeof(Vector));
    }
    return image;
}

void free_image(Vector **image, int height) {
    for (int y = 0; y < height; y++) {
        free(image[y]);
    }
    free(image);
}

void write_image(const char *filename, Vector **image, int width, int height) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        fprintf(stderr, "Error: Could not open file %s for writing\n", filename);
        return;
    }

    fprintf(f, "P3\n%d %d\n255\n", width, height);

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            float r = fmin(fmax(image[y][x].x, 0.0), 1.0);
            float g = fmin(fmax(image[y][x].y, 0.0), 1.0);
            float b = fmin(fmax(image[y][x].z, 0.0), 1.0);
            fprintf(f, "%d %d %d\n", (int)(r * 255.99f), (int)(g * 255.99f), (int)(b * 255.99f));
        }
    }

    fclose(f);
    fprintf(stderr, "Wrote image to %s\n", filename);
}

int main(void) {
    fprintf(stderr, "Creating high-resolution image: %dx%d\n", WIDTH, HEIGHT);
    fprintf(stderr, "This will be downsampled with ffmpeg after rendering\n");

    Sphere sphere;
    sphere.center = vector_create(0.0f, -0.5f, -5.0f);
    sphere.radius = 1.0f;

    Vector light_dir = vector_normalize(vector_create(1.0f, 1.0f, -1.0f));

    Vector origin = vector_create(0.0f, 0.0f, 0.0f);
    Vector lower_left = vector_create(-1.3333333730697632f, -1.0f, -1.0f);
    Vector horizontal = vector_create(2.6666667461395264f, 0.0f, 0.0f);
    Vector vertical = vector_create(0.0f, 2.0f, 0.0f);

    Vector **image = allocate_image(WIDTH, HEIGHT);

    fprintf(stderr, "Rendering high-resolution image...\n");

    for (int y = 0; y < HEIGHT; y++) {
        fprintf(stderr, "\rProgress: %.1f%%", y * 100.0f / HEIGHT);

        float v = 1.0f - (float)y / (HEIGHT - 1);

        for (int x = 0; x < WIDTH; x++) {
            float u = (float)x / (WIDTH - 1);
            Vector direction = vector_add(vector_add(vector_multiply(horizontal, u),
                                                     vector_multiply(vertical, v)),
                                         lower_left);
            Ray ray = ray_create(origin, direction);
            image[y][x] = trace(ray, sphere, light_dir);
        }
    }

    fprintf(stderr, "\nRendering complete\n");

    write_image("image.ppm", image, WIDTH, HEIGHT);
    free_image(image, HEIGHT);

    fprintf(stderr, "Done.\n");
    return 0;
}

